content.text:
{
  "name": "海洋光学光谱仪",
  "name_en": "Ocean Optics Spectrometer",
  "manufacturer": "Ocean Optics",
  "description": "这是一类通过 USB 连接的紧凑型光纤光谱仪，可用于采集样品的吸收、发射或反射光谱。设备内部带有板载 EEPROM 存储区，用于保存设备标识、校准系数和其他配置数据，常见于科研与教学中的光谱测量和仪器信息管理。",
  "description_en": "This is a compact USB fiber-optic spectrometer used to acquire absorption, emission, or reflection spectra from samples. The instrument includes onboard EEPROM storage for device identity, calibration coefficients, and other configuration data, and is commonly used in laboratory spectroscopy and instrument data management.",
  "tag_hints": [
    "USB spectrometer",
    "fiber optic spectroscopy",
    "EEPROM calibration storage",
    "Ocean Optics",
    "spectrometer metadata",
    "optical measurement"
  ],
  "actions": [
    {
      "action_name": "auto-has_eeprom_feature",
      "description": "检查光谱仪是否具有板载 EEPROM 存储功能。",
      "description_en": "Check whether the spectrometer has onboard EEPROM storage functionality."
    },
    {
      "action_name": "auto-read_eeprom_slot",
      "description": "读取光谱仪 EEPROM 指定槽位中的数据。",
      "description_en": "Read the data stored in a specified EEPROM slot of the spectrometer."
    },
    {
      "action_name": "auto-write_eeprom_slot",
      "description": "将数据写入光谱仪 EEPROM 的指定槽位。",
      "description_en": "Write data to a specified EEPROM slot of the spectrometer."
    },
    {
      "action_name": "auto-read_eeprom_slot_raw",
      "description": "读取光谱仪 EEPROM 指定槽位中的原始数据。",
      "description_en": "Read the raw data from a specified EEPROM slot of the spectrometer."
    }
  ]
}

